## CVXPY SOURCE: atoms/log_det.py
## LogDet -- log-determinant of a PSD matrix: log(det(A))


LogDet <- new_class("LogDet", parent = Atom, package = "CVXR",
  constructor = function(A, id = NULL) {
    if (FALSE) new_object(S7_object())  ## S7 static-check guard
    if (is.null(id)) id <- next_expr_id()
    A <- as_expr(A)
    ## Shape is always scalar
    shape <- c(1L, 1L)

    obj <- .fast_new(LogDet, S7_object(),
      id    = as.integer(id),
      .cache = new.env(parent = emptyenv()),
      args  = list(A),
      shape = shape
    )
    validate_arguments(obj)
    obj
  }
)

# -- validate -----------------------------------------------------
## CVXPY: log_det.py lines 50-53
method(validate_arguments, LogDet) <- function(x) {
  A <- .args(x)[[1L]]
  if (length(.shape(A)) != 2L || .shape(A)[1L] != .shape(A)[2L]) {
    cli_abort("The argument to {.fn log_det} must be a square matrix, got shape ({A@shape[1L]}, {A@shape[2L]}).")
  }
  invisible(NULL)
}

# -- shape --------------------------------------------------------
## CVXPY: log_det.py lines 55-58 -- returns tuple()
method(shape_from_args, LogDet) <- function(x) c(1L, 1L)

# -- sign ---------------------------------------------------------
## CVXPY v1.8.2 fix: log_det can be negative (log(det(A)) < 0 when 0 < det(A) < 1).
## Prior to v1.8.2, CVXPY incorrectly returned is_nonneg=TRUE.
method(sign_from_args, LogDet) <- function(x) {
  list(is_nonneg = FALSE, is_nonpos = FALSE)
}

