## CVXPY: log_det.py lines 106-109 -- A >> 0.  This is `_domain()`, the
## atom's OWN constraints; `domain()` (atom.py:545, method(domain, Atom))
## appends the arguments' domains.  Overriding `domain` here dropped them
## (claims audit C0216, 1.9.2.9158).
method(atom_domain, LogDet) <- function(x) {
  list(PSD(.args(x)[[1L]]))
}

