# -- .grad: subgradient of log_det(X) -----------------------------
## CVXPY SOURCE: atoms/log_det.py:85-104 (log_det._grad).
## d/dX log det(X) = X^{-T} on the PSD interior. NULL if min eigenvalue
## <= 0 (outside the open PSD cone). Mirrors CVXPY's LA.eigvalsh
## domain check.
## `tol = 0`: CVXPY's np.linalg.inv has no conditioning test, so an
## ill-conditioned but positive definite X still yields a gradient; base
## solve() would abort "computationally singular" below rcond eps (claims
## audit C0216, 1.9.2.9158; same as .mf_inv in matrix_frac.R).
method(.grad, LogDet) <- function(x, values, ...) {
  X <- as.matrix(values[[1L]])
  ev <- .eigvalsh(X, only_values = TRUE)$values
  if (min(ev) <= 0) return(list(NULL))
  D <- t(solve(X, tol = 0))
  rows <- as.integer(prod(.arg_shape(x)))
  list(.dense_to_csc_vector(as.numeric(D), rows))
}

# ==================================================================
# Convenience function
# ==================================================================

#' Log-determinant
#'
#' Computes log(det(A)) for PSD matrix A.
#'
#' @param A A square PSD matrix expression
#' @returns An expression representing log(det(A))
#' @export
log_det <- function(A) {
  LogDet(A)
}
